// Parser for the generated emoji shortcode table.
//
// The data lives in `emojiShortcodes.txt`, generated by
// `scripts/build-emoji-meta.mjs` from GitHub's gemoji list. This file holds only
// the parse, so the app and the unit tests read the same bytes the same way.
//
// Format, one emoji per line:
//
//   <emoji>\t<alias>|<alias>...\t<unicode version>
//
// The first alias is the one GitHub shows; the rest are alternates. The
// version is the Unicode release that introduced the emoji ("6.1").

export function parseEmojiShortcodes(text) {
  const map = new Map()
  if (typeof text !== 'string') return map
  for (const line of text.split('\n')) {
    const parts = line.split('\t')
    if (parts.length < 2) continue
    const [char, aliases, version = ''] = parts
    const list = aliases.split('|').filter(Boolean)
    if (!char || !list.length) continue
    map.set(char, { aliases: list, version: version.trim() })
  }
  return map
}
